import{_ as e,o as a,c as i,ao as s}from"./chunks/framework.CWHsw1fv.js";const c=JSON.parse('{"title":"Working with other packages","description":"","frontmatter":{},"headers":[],"relativePath":"ecosystem.md","filePath":"ecosystem.md","lastUpdated":null}'),r={name:"ecosystem.md"};function n(o,t,l,h,d,g){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="Working-with-other-packages" tabindex="-1">Working with other packages <a class="header-anchor" href="#Working-with-other-packages" aria-label="Permalink to &quot;Working with other packages {#Working-with-other-packages}&quot;">​</a></h1><p>PureOSQP has <strong>no required dependencies</strong>. Everything on this page is optional: load the package you want and the capability appears, through Julia&#39;s package-extension mechanism or through the solver simply being generic enough not to care.</p><p>Two mechanisms are at work, and it is worth knowing which is which.</p><p><strong>Extensions</strong> are code this package ships that only loads when you load something else. There are seven, listed below. Nothing happens until the trigger package is present.</p><p><strong>Genericity</strong> needs no code at all. The solver is written over <code>T &lt;: Real</code> and reaches <code>P</code> and <code>A</code> through <code>mul!</code>, so a number type or matrix type it has never heard of works if it behaves like a number or a matrix. The precision types below are in this category — there is no &quot;DoubleFloats extension&quot;, and none is needed.</p><h2 id="Number-types" tabindex="-1">Number types <a class="header-anchor" href="#Number-types" aria-label="Permalink to &quot;Number types {#Number-types}&quot;">​</a></h2><p>The element type comes from your arrays; the solver follows it. Everything here was checked by solving the same small QP at each type — identical iteration counts and objectives agreeing to eleven digits.</p><table tabindex="0"><thead><tr><th style="text-align:right;">type</th><th style="text-align:right;">package</th><th style="text-align:right;">digits</th><th style="text-align:right;">cost vs <code>Float64</code></th><th style="text-align:right;">note</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Float32</code></td><td style="text-align:right;">—</td><td style="text-align:right;">~7</td><td style="text-align:right;">—</td><td style="text-align:right;">works; halves memory</td></tr><tr><td style="text-align:right;"><code>Float64</code></td><td style="text-align:right;">—</td><td style="text-align:right;">~16</td><td style="text-align:right;">1×</td><td style="text-align:right;">the default</td></tr><tr><td style="text-align:right;"><code>Double64</code></td><td style="text-align:right;"><a href="https://github.com/JuliaMath/DoubleFloats.jl" target="_blank" rel="noreferrer">DoubleFloats.jl</a></td><td style="text-align:right;">~32</td><td style="text-align:right;">~22×</td><td style="text-align:right;"><strong>the pick for extra precision</strong></td></tr><tr><td style="text-align:right;"><code>Float128</code></td><td style="text-align:right;"><a href="https://github.com/JuliaMath/Quadmath.jl" target="_blank" rel="noreferrer">Quadmath.jl</a></td><td style="text-align:right;">~34</td><td style="text-align:right;">~85×</td><td style="text-align:right;">software-emulated</td></tr><tr><td style="text-align:right;"><code>BigFloat</code></td><td style="text-align:right;">stdlib</td><td style="text-align:right;">tunable</td><td style="text-align:right;">~264×</td><td style="text-align:right;">arbitrary precision</td></tr></tbody></table><p><code>Double64</code> is roughly four times faster than <code>Float128</code> at the same precision, because it is double-double arithmetic — a pair of <code>Float64</code>s using hardware floating point — where <code>Float128</code> is emulated in software. If you want more than <code>Float64</code>, start there.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PureOSQP, DoubleFloats</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sol </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> solve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Double64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(P), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Double64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(q), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Double64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(A), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Double64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(l), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Double64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(u))</span></span></code></pre></div><p><strong><code>Rational</code> does not work</strong>, and the reason is inherent rather than a gap here: exact rational arithmetic grows denominators without bound, and <code>Rational{Int}</code> overflows within a few iterations. <code>Rational{BigInt}</code> avoids the overflow at a cost that makes it impractical.</p><p><strong>More precision does not make an ill-conditioned problem converge faster.</strong> This is worth saying plainly because it is a natural thing to reach for. The iteration count is a property of the problem&#39;s geometry, not of the arithmetic: at every precision above, the same problem took the same 250 iterations. Extra precision lowers the floor on achievable accuracy; it does not speed the descent toward it. If a badly conditioned problem is stopping at <code>max_iter</code>, see <a href="/PureOSQP.jl/dev/benchmarks#Conditioning">Conditioning</a> — the lever there is structure, not bits.</p><h2 id="Matrix-and-operator-types" tabindex="-1">Matrix and operator types <a class="header-anchor" href="#Matrix-and-operator-types" aria-label="Permalink to &quot;Matrix and operator types {#Matrix-and-operator-types}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">package</th><th style="text-align:right;">what it buys</th><th style="text-align:right;">how</th></tr></thead><tbody><tr><td style="text-align:right;"><code>LinearAlgebra</code> (stdlib)</td><td style="text-align:right;"><code>Diagonal</code>, <code>Bidiagonal</code>, <code>SymTridiagonal</code>, <code>Tridiagonal</code>, <code>Symmetric</code>, views</td><td style="text-align:right;">genericity, plus dedicated backends</td></tr><tr><td style="text-align:right;"><a href="https://github.com/JuliaSparse/SparseArrays.jl" target="_blank" rel="noreferrer">SparseArrays</a> (stdlib)</td><td style="text-align:right;">sparse <code>P</code> and <code>A</code>, walked by stored entry</td><td style="text-align:right;">extension</td></tr><tr><td style="text-align:right;"><a href="https://github.com/JuliaLinearAlgebra/BandedMatrices.jl" target="_blank" rel="noreferrer">BandedMatrices.jl</a></td><td style="text-align:right;">bandwidth ≥ 2, which LinearAlgebra has no symmetric type for</td><td style="text-align:right;">extension</td></tr><tr><td style="text-align:right;"><a href="https://github.com/JuliaLinearAlgebra/LinearMaps.jl" target="_blank" rel="noreferrer">LinearMaps.jl</a></td><td style="text-align:right;">an operator you can apply but never store</td><td style="text-align:right;">extension</td></tr><tr><td style="text-align:right;"><a href="https://github.com/JuliaSmoothOptimizers/Krylov.jl" target="_blank" rel="noreferrer">Krylov.jl</a></td><td style="text-align:right;">the matrix-free backend, needed for any operator</td><td style="text-align:right;">extension</td></tr><tr><td style="text-align:right;"><a href="https://github.com/JuliaSmoothOptimizers/LDLFactorizations.jl" target="_blank" rel="noreferrer">LDLFactorizations.jl</a></td><td style="text-align:right;">a pure-Julia sparse <code>LDLᵀ</code> instead of SuiteSparse</td><td style="text-align:right;">extension</td></tr><tr><td style="text-align:right;"><a href="https://github.com/JuliaGPU/GPUArrays.jl" target="_blank" rel="noreferrer">GPUArraysCore.jl</a></td><td style="text-align:right;">GPU arrays, matrix-free only</td><td style="text-align:right;">extension</td></tr></tbody></table><p>Which of these to reach for is a question about your problem, answered with measurements in <a href="/PureOSQP.jl/dev/matrices#Which-representation,-and-why">Which representation, and why</a>.</p><p>Two are worth singling out. <strong>LDLFactorizations</strong> is not only a speed choice: it is what makes a sparse problem <code>juliac --trim</code> compatible, because it replaces a SuiteSparse <code>ccall</code> no static analysis can resolve — see <a href="/PureOSQP.jl/dev/guarantees#Guarantees">Guarantees</a>. <strong>Krylov</strong> is required, not optional, for any operator that cannot be materialized; without it there is no backend that can serve one.</p><h2 id="Modelling-and-interfaces" tabindex="-1">Modelling and interfaces <a class="header-anchor" href="#Modelling-and-interfaces" aria-label="Permalink to &quot;Modelling and interfaces {#Modelling-and-interfaces}&quot;">​</a></h2><p><a href="https://github.com/jump-dev/MathOptInterface.jl" target="_blank" rel="noreferrer">MathOptInterface.jl</a> has an extension, so PureOSQP is usable as a JuMP solver:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JuMP, PureOSQP, MathOptInterface</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(PureOSQP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Optimizer)</span></span></code></pre></div><p>The wrapper passes <code>MOI.Test</code>, which is a far more thorough conformance suite than anything hand-written.</p><h2 id="Differentiating-a-solve" tabindex="-1">Differentiating a solve <a class="header-anchor" href="#Differentiating-a-solve" aria-label="Permalink to &quot;Differentiating a solve {#Differentiating-a-solve}&quot;">​</a></h2><p>There are two ways, and they answer different questions.</p><p><strong>Built in, no dependency.</strong> <a href="/PureOSQP.jl/dev/api#PureOSQP.adjoint_derivative"><code>PureOSQP.adjoint_derivative</code></a> and <a href="/PureOSQP.jl/dev/api#PureOSQP.forward_derivative"><code>PureOSQP.forward_derivative</code></a> differentiate the <em>solution</em> by implicit differentiation of the KKT conditions at the active set. One linear solve, independent of how many iterations the solve took, reusing a factorization the solver already has.</p><p><strong>Through the iterations, with ForwardDiff.</strong> Because the solver is generic over <code>T &lt;: Real</code>, <code>ForwardDiff.Dual</code> numbers pass straight through it and you can differentiate any function of the result:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PureOSQP, ForwardDiff</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ForwardDiff</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">derivative</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(t </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> solve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P, q </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> t, A, l, u)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">obj_val, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Checked against central differences on a small QP: agreement to <code>5e-11</code>.</p><p><strong>Prefer the built-in one for anything real.</strong> Forward mode costs one solve per parameter, and <code>P</code> alone has <code>n²</code> of them; and it differentiates <code>x_N(θ)</code>, the iterate you stopped at, rather than <code>x*(θ)</code>, the solution. They converge to the same thing, but the implicit form gets there in one solve and does not depend on the path taken. ForwardDiff&#39;s value here is as an independent check on the implicit derivative — exact, with no finite-difference step to choose — which is what the package&#39;s own tests use it for.</p>`,27)])])}const y=e(r,[["render",n]]);export{c as __pageData,y as default};
